// Gate strip images by the document viewport, not their nested horizontal scrollport.
function loadTeachingPictures(panel) {
  Array.prototype.forEach.call(panel.querySelectorAll('img[data-sh-src]'), function (image) {
    image.src = image.getAttribute('data-sh-src');
    image.removeAttribute('data-sh-src');
  });
}
var picturePanels = document.querySelectorAll('.sefer-hamidos-media');
if ('IntersectionObserver' in window) {
  var pictureObserver = new IntersectionObserver(function (entries) {
    entries.forEach(function (entry) {
      clearTimeout(entry.target._shPictureTimer);
      if (!entry.isIntersecting) return;
      // Do not hydrate teachings passed during automatic fragment scrolling.
      entry.target._shPictureTimer = setTimeout(function () {
        var rect = entry.target.getBoundingClientRect();
        if (rect.bottom < -600 || rect.top > window.innerHeight + 600) return;
        loadTeachingPictures(entry.target);
        pictureObserver.unobserve(entry.target);
      }, 200);
    });
  }, { rootMargin: '600px 0px' });
  Array.prototype.forEach.call(picturePanels, function (panel) { pictureObserver.observe(panel); });
} else {
  Array.prototype.forEach.call(picturePanels, loadTeachingPictures);
}
